package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var l, r, x, y int64
	fmt.Fscan(in, &l, &r, &x, &y)

	if y%x != 0 {
		fmt.Println(0)
		return
	}

	k := y / x
	if k == 1 {
		if x >= l && x <= r {
			fmt.Println(1)
		} else {
			fmt.Println(0)
		}
		return
	}

	// Factorize k
	factors := factorize(k)

	// Generate all divisors of k
	divisors := []int64{1}
	for p, e := range factors {
		newDivs := []int64{}
		pe := int64(1)
		for i := 0; i <= e; i++ {
			for _, d := range divisors {
				newDivs = append(newDivs, d*pe)
			}
			pe *= p
		}
		divisors = newDivs
	}

	count := 0
	for _, d := range divisors {
		a := x * d
		b := x * (k / d)
		if a >= l && a <= r && b >= l && b <= r {
			count++
		}
	}

	fmt.Println(count)
}

func factorize(n int64) map[int64]int {
	factors := make(map[int64]int)
	d := int64(2)
	for d*d <= n {
		for n%d == 0 {
			factors[d]++
			n /= d
		}
		d++
	}
	if n > 1 {
		factors[n]++
	}
	return factors
}
